// mapping-loader (spec M7 §5, §4.4) — init a ogni deploy/avvio (inject once).
// Legge /data/tag-mapping.js (file GENERATO da edge/tag-mapping.yaml, unica
// fonte §4.4), estrae module.exports (array di {logical_name, node_id,
// datatype, unit, access, sampling_mode}) e lo espone nel context del flow.
// Nessun NodeId hard-coded nei flow (AC-M7-4): i node_id vivono solo nel
// mapping. Se il file manca/non è valido: log errore chiaro e no-op.
var MAPPING_FILE = '/data/tag-mapping.js';
var mapping = null;
try {
    var src = fs.readFileSync(MAPPING_FILE, 'utf8');
    // Estrae l'array JSON tra il '[' che segue "module.exports" e l'ultimo ']'
    // (formato deterministico del generatore: "module.exports = [ ... ];" —
    // niente eval/Function). NB: il '[' del commento di testa NON conta.
    var marker = src.lastIndexOf('module.exports');
    var start = src.indexOf('[', marker >= 0 ? marker : 0);
    var end = src.lastIndexOf(']');
    if (start < 0 || end <= start) {
        throw new Error('formato inatteso: nessun array JSON in ' + MAPPING_FILE);
    }
    // Il generatore lascia una virgola finale prima di ']' (JS valido, JSON no):
    // la si rimuove prima del parse.
    var arrSrc = src.slice(start, end + 1).replace(/,\s*\]\s*$/, ']');
    mapping = JSON.parse(arrSrc);
} catch (err) {
    node.error('[mapping-loader] file non leggibile o mapping non valido: ' + err.message +
        ' — acquisizione DISATTIVATA (no-op). Rigenerare il mapping con: ' +
        'python edge/scripts/build_tag_mapping.py (da edge/tag-mapping.yaml, unica fonte)');
    flow.set('m7.tagMapping', null);
    flow.set('m7.nodeIndex', null);
    flow.set('m7.ready', false);
    node.status({ fill: 'red', shape: 'ring', text: 'mapping: NON caricato' });
    return null; // no-op: nessuna subscription, nessuna acquisizione
}
// Validazione di base: ogni voce deve avere logical_name e node_id (formato §4.4).
var bad = mapping.filter(function (e) { return !e || !e.logical_name || !e.node_id; });
if (bad.length > 0) {
    node.warn('[mapping-loader] ' + bad.length + ' voce/i senza logical_name/node_id — ignorate');
    mapping = mapping.filter(function (e) { return e && e.logical_name && e.node_id; });
}
if (mapping.length === 0) {
    node.error('[mapping-loader] mapping vuoto dopo la validazione — no-op');
    flow.set('m7.ready', false);
    return null;
}
// Indicizzazione node_id -> logical_name (le notifiche di subscription portano
// il nodeId come msg.topic).
var index = {};
mapping.forEach(function (e) { index[e.node_id] = e.logical_name; });

// Stato di acquisizione: ogni deploy/riavvio è un NUOVO epoch (spec §10 Q1:
// watermark in-memory, niente backfill, niente duplicati).
flow.set('m7.tagMapping', mapping);
flow.set('m7.nodeIndex', index);
flow.set('m7.ready', true);
flow.set('m7.watermark', null);
flow.set('m7.initCc', null);
flow.set('m7.tagStore', {});

var triggers = mapping.filter(function (e) { return /^machine\./.test(e.logical_name); }).length;
var block = mapping.filter(function (e) { return /^valve01\./.test(e.logical_name); }).length;
node.log('[mapping-loader] mapping caricato: ' + mapping.length + ' voci (' + triggers +
    ' trigger machine.* + ' + block + ' valve01.*) da ' + MAPPING_FILE);
// NB: la verifica browse dei node_id (spec §5) è delegata a T0
// (edge/tests/parity_check.py, browse asyncua): da un function node non è
// possibile fare un browse sincrono.
node.status({ fill: 'green', shape: 'dot', text: 'mapping: ' + mapping.length + ' voci' });
return msg;

// subscription-setup (spec §5, §4.3) — costruisce la subscription OPC UA a runtime.
//
// PLACEHOLDER (AC-M7-4): nessun NodeId nei flow. I nodeId sono risolti a
// runtime dal mapping loader (flow context "m7.tagMapping"):
//   - trigger: machine.data_ready + machine.cycle_counter  (logica §4.3:
//     trigger = DataReady || CycleCounter; CycleCounter è la fonte di verità,
//     DataReady solo reattività — il pulse di 10 ms può andare perso, §4.1);
//   - blocco : valve01.* (13 tag) — i valori arrivano via subscription e
//     restano nello store del context per la lettura blocco (§4.3 passo 4).
// Se il mapping non è nel context (loader no-op) NON si sottoscrive nulla.
var mapping = flow.get('m7.tagMapping');
if (!mapping || mapping.length === 0) {
    node.warn('[subscribe] mapping non disponibile nel context — subscription NON creata ' +
        '(no-op); verificare il mapping loader (/data/tag-mapping.js)');
    node.status({ fill: 'red', shape: 'ring', text: 'subscribe: SKIP (no mapping)' });
    return null;
}
var triggers = [];
var block = [];
mapping.forEach(function (e) {
    if (e.logical_name === 'machine.data_ready' || e.logical_name === 'machine.cycle_counter') {
        triggers.push({ nodeId: e.node_id });
    } else if (e.logical_name && e.logical_name.indexOf('valve01.') === 0) {
        block.push({ nodeId: e.node_id });
    }
});
if (triggers.length === 0 || block.length === 0) {
    node.warn('[subscribe] mapping incompleto: trigger=' + triggers.length +
        ' block=' + block.length + ' — subscription NON creata');
    return null;
}
node.log('[subscribe] subscription: ' + triggers.length + ' trigger (DataReady, CycleCounter) + ' +
    block.length + ' tag blocco valve01.* (nodeId dal mapping, mai hard-coded)');
node.status({ fill: 'blue', shape: 'dot', text: 'subscribe: ' + (triggers.length + block.length) + ' items' });
var out = [];
// NB (deviazione collaudo M7): il msg deletesubscription del watchdog è stato
// RIMOSSO — la palette node-red-contrib-opcua 0.2.354 (unica disponibile in
// questo ambiente) dispaccia sull'action config del client ignorando msg.action:
// il msg finiva nel path single-item con topic 'subscription' → nodeId invalido →
// eccezione non catturata → crash del processo ogni ~30 s. Restano i re-subscribe
// 'multiple' (duplicano gli item sulla stessa subscription: dedup watermark ok);
// azione M8: palette 2.x o action native (vedi report di accettazione M7 §4, documento locale).
out.push({ topic: 'multiple', payload: triggers });
out.push({ topic: 'multiple', payload: block });
return [out];

// watermark-acquisition (spec M7 §4.3 — modello watermark, niente ack server).
// Ingresso: notifiche di subscription dal client OPC UA (output 0, group
// "multiple"): msg.topic = node_id sottoscritto; msg.payload = DataValue
// {value:{value,dataType}, statusCode, sourceTimestamp, serverTimestamp}
// (timestamp in ms epoch o Date; statusCode.value 0 = Good).
// Ogni notifica aggiorna lo store dei tag nel context (in-memory); le notifiche
// su machine.data_ready | machine.cycle_counter attivano il check watermark:
//   1) init: alla prima notifica watermark = CycleCounter corrente (nessun backfill)
//   2) cc <= watermark -> ignora (nessun duplicato)
//   3) cc < watermark  -> epoch reset (server riavviato): watermark = cc + log
//   4) cc > watermark  -> nuova chiusura ciclo: burst (delta>1) loggato (metrica
//      §89), lettura blocco 13 tag valve01.* via mapping dal context, aggiornamento
//      watermark, emissione al builder.
// Nessuna logica di business: solo confronto di contatori e letture (spec §2.3).
var mapping = flow.get('m7.tagMapping');
var index = flow.get('m7.nodeIndex');
if (!mapping || !index) {
    node.warn('[watermark] mapping assente nel context — skip');
    return null;
}
var logical = index[msg.topic];
if (!logical) {
    node.warn('[watermark] nodeId non presente nel mapping: ' + msg.topic);
    return null;
}
// --- estrazione valore + qualità OPC UA + ServerTimestamp dalla DataValue ---
var dv = msg.payload || {};
var sc = dv.statusCode;
var good = true;
if (sc !== undefined && sc !== null) {
    good = (typeof sc.value === 'number') ? (sc.value === 0) : true; // 0x00000000 = Good
}
var raw = null;
if (dv.value !== undefined && dv.value !== null) {
    raw = (typeof dv.value === 'object' && 'value' in dv.value) ? dv.value.value : dv.value;
}
var val = null;
if (good) {
    try {
        // Int64 da node-opcua legacy (palette 0.2.x): valore come array [high, low]
        // — combinazione in numero (deviazione registrata nel collaudo M7).
        if (Array.isArray(raw) && raw.length === 2) { val = raw[0] * 4294967296 + raw[1]; }
        else { val = (typeof raw === 'bigint') ? Number(raw) : raw; }
    }
    catch (e) { val = null; }
}
var serverMs = null;
var st = dv.serverTimestamp;
if (st instanceof Date) { serverMs = st.getTime(); }
else if (typeof st === 'number') { serverMs = st; }
else if (st) { try { serverMs = new Date(st).getTime(); } catch (e) { serverMs = null; } }

var store = flow.get('m7.tagStore') || {};
store[logical] = { v: val, ts: serverMs, good: good };
flow.set('m7.tagStore', store);

// --- trigger §4.3: DataReady || CycleCounter ---
if (logical !== 'machine.data_ready' && logical !== 'machine.cycle_counter') {
    return null; // aggiornamento di un tag di blocco: solo store
}
var ccEntry = store['machine.cycle_counter'];
if (!ccEntry || ccEntry.v === null || ccEntry.v === undefined) {
    return null; // CycleCounter non ancora osservato: niente check
}
var cc = ccEntry.v;
var wm = flow.get('m7.watermark');

if (wm === null || wm === undefined) {
    // 1) init: nessun backfill — watermark = CycleCounter corrente
    flow.set('m7.watermark', cc);
    flow.set('m7.initCc', cc);
    node.log('[watermark] init: watermark = CycleCounter ' + cc +
        ' (nessun backfill dei cicli chiusi durante il down)');
    node.status({ fill: 'green', shape: 'dot', text: 'watermark init: ' + cc });
    return null;
}
if (cc < wm) {
    // 3) epoch reset: server riavviato (contatori ripartono da 0)
    flow.set('m7.watermark', cc);
    node.warn('[watermark] epoch reset: CycleCounter ' + cc + ' < watermark ' + wm +
        ' (server riavviato) — nuovo epoch, watermark = ' + cc);
    node.status({ fill: 'yellow', shape: 'ring', text: 'epoch reset: ' + cc });
    return null;
}
if (cc > wm) {
    // 4) nuova chiusura ciclo
    var gaps = cc - wm - 1;
    if (gaps > 0) {
        // burst (limite documentato §4.3): blocchi intermedi non più leggibili —
        // si pubblica l'ultimo blocco leggibile e si LOGGA il gap (metrica §89).
        node.warn('[watermark] GAP: ' + gaps + ' ciclo/i chiusi tra watermark ' + wm +
            ' e CycleCounter ' + cc + ' non più leggibili — pubblicato ' +
            "l'ultimo blocco leggibile (spec §4.3, metrica §89)");
    }
    // lettura blocco: 13 tag valve01.* via mapping dal context (spec §4.3 passo 4)
    var block = {};
    var sourceTs = null;
    mapping.forEach(function (e) {
        if (e.logical_name && e.logical_name.indexOf('valve01.') === 0) {
            var s = store[e.logical_name];
            block[e.logical_name] = (s && s.good) ? s.v : null;
            if (s && s.ts !== null && s.ts !== undefined) {
                if (sourceTs === null || s.ts > sourceTs) { sourceTs = s.ts; }
            }
        }
    });
    flow.set('m7.watermark', cc);
    node.status({ fill: 'green', shape: 'dot', text: 'cycle ' + cc });
    return { payload: { cycleCounter: cc, block: block, sourceTs: sourceTs } };
}
// 2) cc === watermark: ignora (nessun duplicato)
return null;

// builder-envelope (spec M7 §4.2): costruisce l'envelope JSON v1.0 ESATTAMENTE
// conforme a edge/schemas/envelope-v1.json. Nessuna logica di business: solo
// normalizzazione e impacchettamento (spec §2.3).
// Ingresso: { payload: { cycleCounter, block, sourceTs } } dal watermark.
var p = msg.payload || {};
var block = p.block || {};
var cc = p.cycleCounter;
var sourceTsMs = p.sourceTs; // ServerTimestamp del blocco (ms epoch o Date) o null

// event_id: uuid v4 — crypto.randomUUID se disponibile, fallback v4 timestamp-based.
var eventId = null;
try { eventId = crypto.randomUUID(); } catch (e) { eventId = null; }
if (!eventId) {
    eventId = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
        var r = Math.random() * 16 | 0;
        var v = (c === 'x') ? r : ((r & 0x3) | 0x8);
        return v.toString(16);
    });
}

// event_ts: ISO8601 UTC, orologio edge (Node-RED) all'arrivo del dato (§4.2).
var eventTs = new Date().toISOString();
// source_ts: ServerTimestamp del blocco Valve01 se disponibile (≈ chiusura
// ciclo, spec §10 Q3), fallback event_ts.
var sourceTs = eventTs;
if (sourceTsMs !== null && sourceTsMs !== undefined) {
    try {
        var d = (sourceTsMs instanceof Date) ? sourceTsMs : new Date(sourceTsMs);
        if (!isNaN(d.getTime())) { sourceTs = d.toISOString(); }
    } catch (e) { /* fallback: event_ts */ }
}

// valve_id: derivata dal mapping (gruppo valveNN, §4.2) — in M7 sempre 1.
var valveId = 1;
var mapping = flow.get('m7.tagMapping') || [];
var valveEntry = null;
mapping.forEach(function (e) {
    if (!valveEntry && e.logical_name && e.logical_name.indexOf('valve') === 0) {
        valveEntry = e.logical_name;
    }
});
var m = valveEntry ? /^valve(\d+)/.exec(valveEntry) : null;
if (m) { valveId = parseInt(m[1], 10); }
// Prefisso del gruppo blocco (es. valve01): il blocco dal watermark è indicizzato
// per logical_name del mapping (prefisso valveNN., §4.4); le chiavi data.*
// dell'envelope v1.0 sono le chiavi SENZA prefisso (schema envelope-v1.json,
// DATA_KEYS di parity_check) — si estrae la parte dopo il prefisso.
var prefix = 'valve' + (valveId < 10 ? '0' + valveId : valveId);

// data.* — 15 campi del contratto (chiavi corte, schema v1.2 M9).
// Tag non leggibile (qualità OPC UA cattiva, valore mancante) => null e
// quality.valid=false, completeness='partial' (policy T6, nessun ciclo sparisce).
var DATA_KEYS = ['filling_time_ms', 'tail_time_ms', 'tail_pulse', 'pulse_count',
    'target', 'delta_pulse', 'filling_step_out', 'filling_ok',
    'fill_quality_ok', 'sequence_ok', 'sample_valid', 'diagnostic_status',
    'close_reason', 'position_limit', 'filling_overtime'];
var data = {};
var complete = true;
DATA_KEYS.forEach(function (k) {
    var v = block[prefix + '.' + k];
    if (v === undefined || v === null) {
        data[k] = null;
        complete = false;
    } else {
        try { data[k] = (typeof v === 'bigint') ? Number(v) : v; }
        catch (e) { data[k] = null; complete = false; }
    }
});

// cycle_id = Valve01.LastCycleId (Int64, identità del ciclo, §4.1); fallback:
// CycleCounter corrente (lockstep M6) con log — il record resta schema-valido.
var cycleId = block[prefix + '.last_cycle_id'];
if (cycleId === undefined || cycleId === null) {
    cycleId = cc;
    complete = false;
    node.warn('[builder] LastCycleId non leggibile: cycle_id = CycleCounter ' + cc +
        ' (fallback, lockstep spec §4.1)');
}
try {
    // Int64 da node-opcua legacy (palette 0.2.x): array [high, low] — combinazione
    // in numero (deviazione registrata nel collaudo M7).
    if (Array.isArray(cycleId) && cycleId.length === 2) { cycleId = cycleId[0] * 4294967296 + cycleId[1]; }
    else { cycleId = Number(cycleId); }
} catch (e) { cycleId = 0; complete = false; }

var env = {
    schema_version: '1.2',
    event_id: eventId,
    event_type: 'valve_cycle',
    event_ts: eventTs,
    source_ts: sourceTs,
    machine_id: 'filler01',
    cycle_id: cycleId,
    valve_id: valveId,
    data: data,
    quality: { valid: complete, completeness: complete ? 'complete' : 'partial' }
};
node.status({ fill: 'green', shape: 'dot', text: 'env ' + env.cycle_id });
msg.payload = env;
return msg;

// test-sink (spec §5): append dell'envelope in JSON compatto (una riga per
// record) su /data/out/out.jsonl — mount host-side: edge/out/out.jsonl
// (edge/docker-compose.yml). Variante di deploy per il collaudo (T1/T3-T6).
var OUT_FILE = '/data/out/out.jsonl';
var record = msg.payload;
if (!record) {
    node.warn('[test-sink] nessun envelope in msg.payload — skip');
    return null;
}
try {
    fs.appendFileSync(OUT_FILE, JSON.stringify(record) + '\n', { encoding: 'utf8', flag: 'a', mode: 0o644 });
    node.status({ fill: 'green', shape: 'dot', text: 'appended ' + record.cycle_id });
    node.log('[test-sink] append ok: cycle_id=' + record.cycle_id + ' -> ' + OUT_FILE);
} catch (err) {
    node.error('[test-sink] append FALLITO: ' + err.message + ' (verificare il mount ' +
        './out:/data/out nel docker-compose.yml)');
    node.status({ fill: 'red', shape: 'ring', text: 'append error' });
}
return null;
